331	// TestRecreateHandoverAfterToShiftClosed：某次交接全部处理完成、接班班次随后
332	// 结束（事项又在后续班次关闭或继续流转）后，用原交班/接班编号重复发起必须视为
333	// 成功返回已有记录：原交接编号、两班关系、发起与完成时间、各事项当时的确认/
334	// 跟踪结果、处理人、处理时间以及退回与补充经过全部沿用原值，不重新挑选清单、
335	// 不重新接收、不移动事项、不追加经过。改换接班对象（无论新对象是否结束）一律
336	// 拒绝并指出原接班班次，且不得生成第二条交接；不存在的编号仍然报错。
337	func TestRecreateHandoverAfterToShiftClosed(t *testing.T) {
338		f := newFixture(t)
339		a, b, items := prepareHandover(t, f)
340		h1, err := f.svc.CreateHandover(a.ID, b.ID)
341		if err != nil {
342			t.Fatalf("create: %v", err)
343		}
344		idA, idB := items[0].ID, items[1].ID
345	
346		// 乙先退回、交班人补充后再继续跟踪，保留一轮退回/补充经过；甲确认接收。
347		if _, err := f.svc.ProcessEntry(h1.ID, idB, ActionReturn, "李四", "需要补充细节", "", ""); err != nil {
348			t.Fatalf("return: %v", err)
349		}
350		if _, err := f.svc.ResubmitReturned(h1.ID, idB, "张三", "补充说明如下"); err != nil {
351			t.Fatalf("resubmit: %v", err)
352		}
353		if _, err := f.svc.ProcessEntry(h1.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
354			t.Fatalf("confirm: %v", err)
355		}
356		if _, err := f.svc.ProcessEntry(h1.ID, idB, ActionTrack, "李四", "", "继续盯压力", "王五"); err != nil {
357			t.Fatalf("track: %v", err)
358		}
359		h1, _ = f.svc.GetHandover(h1.ID)
360		if !h1.Completed() || h1.CompletedAt == nil {
361			t.Fatalf("全部处理后交接应已完成")
362		}
363		createdAt, completedAt := h1.CreatedAt, *h1.CompletedAt
364	
365		// 接班班次结束；事项继续流转到下一班 c，甲在 c 关闭。
366		if _, err := f.svc.CloseShift(b.ID); err != nil {
367			t.Fatalf("close b: %v", err)
368		}
369		c := mustShift(t, f, "调度", "赵六", tsDay(2, 23, 0), tsDay(3, 7, 0), "")
370		h2, err := f.svc.CreateHandover(b.ID, c.ID)
371		if err != nil {
372			t.Fatalf("chain handover: %v", err)
373		}
374		if _, err := f.svc.ProcessEntry(h2.ID, idA, ActionConfirm, "赵六", "", "", ""); err != nil {
375			t.Fatalf("confirm on c: %v", err)
376		}
377		if _, err := f.svc.ProcessEntry(h2.ID, idB, ActionTrack, "赵六", "", "持续跟进", "孙七"); err != nil {
378			t.Fatalf("track on c: %v", err)
379		}
380		if _, err := f.svc.CloseItem(idA, "赵六"); err != nil {
381			t.Fatalf("close item on c: %v", err)
382		}
383	
384		snapshot := func() string {
385			raw, err := json.Marshal(f.store.data)
386			if err != nil {
387				t.Fatalf("marshal: %v", err)
388			}
389			return string(raw)
390		}
391		before := snapshot()
392	
393		// 用原来的交班、接班编号重复发起：返回原记录（ErrHandoverExists），命令行
394		// 据此视为成功；即使接班班次 b 已结束也不再报“接班班次已结束”。
395		again, err := f.svc.CreateHandover(a.ID, b.ID)
396		if !errors.Is(err, ErrHandoverExists) {
397			t.Fatalf("接班班次结束后重复发起应返回 ErrHandoverExists，got %v", err)
398		}
399		stored, _ := f.svc.GetHandover(h1.ID)
400		if again.ID != h1.ID || again.FromShiftID != a.ID || again.ToShiftID != b.ID {
401			t.Fatalf("应返回原交接 %s 及原两班关系，got %+v", h1.ID, again)
402		}
403		if !again.CreatedAt.Equal(createdAt) || again.CompletedAt == nil || !again.CompletedAt.Equal(completedAt) {
404			t.Fatalf("发起时间与完成时间应沿用原值：created %v->%v completed %v->%v",
405				createdAt, again.CreatedAt, completedAt, again.CompletedAt)
406		}
407		if len(again.Entries) != 2 {
408			t.Fatalf("仍应展示原交接的2项清单，而不是按最新班次重新挑选，got %d", len(again.Entries))
409		}
410		got := map[string]HandoverEntry{}
411		for _, e := range again.Entries {
412			got[e.ItemID] = e
413		}
414		ea, eb := got[idA], got[idB]
415		if ea.Status != EntryConfirmed || ea.Operator != "李四" || ea.ProcessedAt == nil {
416			t.Fatalf("甲的确认结果/处理人/处理时间应沿用原值：%+v", ea)
417		}
418		if eb.Status != EntryTracking || eb.Operator != "李四" || eb.ProcessedAt == nil ||
419			eb.TrackingNote != "继续盯压力" || eb.FollowOwner != "王五" {
420			t.Fatalf("乙的继续跟踪结果应沿用原值：%+v", eb)
421		}
422		if len(eb.Rounds) != 1 {
423			t.Fatalf("退回与补充经过应保留，got %d 轮", len(eb.Rounds))
424		}
425		r := eb.Rounds[0]
426		if r.Reason != "需要补充细节" || r.ReturnOperator != "李四" ||
427			r.Supplement != "补充说明如下" || r.SupplementOperator != "张三" ||
428			r.ResubmittedAt == nil {
429			t.Fatalf("退回原因、补充说明、补充人与重新提交时间应原样保留：%+v", r)
430		}
431		// 返回的记录与存储中的原记录逐项一致。
432		if fmt.Sprintf("%+v", again) != fmt.Sprintf("%+v", stored) {
433			t.Fatalf("返回内容应为保存的完整原记录\nwant %+v\ngot  %+v", stored, again)
434		}
435	
436		// 重复返回不改动任何数据：不生成新交接、不移动事项、不追加事件或经过。
437		if after := snapshot(); after != before {
438			t.Fatalf("重复发起不得写入或移动任何数据\nbefore %s\nafter  %s", before, after)
439		}
440		if hs := f.svc.ListHandovers(); len(hs) != 2 {
441			t.Fatalf("不应生成第二条交接，期望仍为2条，got %d", len(hs))
442		}
443	
444		// 改换为一个确实存在、但已结束的班次：仍按改换对象拒绝并指出原接班班次，
445		// 不能因为新对象已结束而报“接班班次已结束”，更不能产生第二条交接。
446		d := mustShift(t, f, "调度", "钱七", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
447		if _, err := f.svc.CloseShift(d.ID); err != nil {
448			t.Fatalf("close d: %v", err)
449		}
450		_, err = f.svc.CreateHandover(a.ID, d.ID)
451		if !errors.Is(err, ErrHandoverTarget) || !strings.Contains(err.Error(), b.ID) {
452			t.Fatalf("改换为已结束班次应报 ErrHandoverTarget 并指出原接班班次 %s，got %v", b.ID, err)
453		}
454	
455		// 改换为尚未结束的其他班次同样拒绝。
456		open := mustShift(t, f, "调度", "孙八", tsDay(3, 16, 0), tsDay(4, 0, 0), "")
457		if _, err := f.svc.CreateHandover(a.ID, open.ID); !errors.Is(err, ErrHandoverTarget) {
458			t.Fatalf("改换为未结束班次也应报 ErrHandoverTarget，got %v", err)
459		}
