632	func TestReturnAndResubmit(t *testing.T) {
633		f := newFixture(t)
634		a, b, items := prepareHandover(t, f)
635		h, _ := f.svc.CreateHandover(a.ID, b.ID)
636		idA, idB := items[0].ID, items[1].ID
637	
638		// 退回第一项，交接保持未完成；退回项不进入接班清单。
639		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "信息不全，需补充图纸", "", ""); err != nil {
640			t.Fatalf("return: %v", err)
641		}
642		got, _ := f.svc.GetHandover(h.ID)
643		if got.Completed() {
644			t.Fatalf("存在退回项时交接不应完成")
645		}
646		itA, _ := f.svc.GetItem(idA)
647		if itA.CurrentShiftID != a.ID {
648			t.Fatalf("退回项不应流转到接班班次")
649		}
650	
651		// 接班班次存在退回项时不能结束。
652		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
653			t.Fatalf("confirm: %v", err)
654		}
655		if _, err := f.svc.CloseShift(b.ID); !errors.Is(err, ErrHandoverState) {
656			t.Fatalf("仍有退回交接项时接班班次不能结束，got %v", err)
657		}
658	
659		// 交班人补充说明不能为空。
660		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "   "); !errors.Is(err, ErrInvalidInput) {
661			t.Fatalf("补充说明必须非空，got %v", err)
662		}
663		// 非退回项不能重新提交。
664		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充"); !errors.Is(err, ErrHandoverState) {
665			t.Fatalf("已确认项不能重新提交，got %v", err)
666		}
667		// 补充并重新提交：只有该项恢复待处理，既有接收结果不变。
668		if _, err := f.svc.ResubmitReturned(h.ID, idA, " 张三 ", "图纸编号已补到资料柜B层"); err != nil {
669			t.Fatalf("resubmit: %v", err)
670		}
671		got, _ = f.svc.GetHandover(h.ID)
672		var ea, eb *HandoverEntry
673		for i := range got.Entries {
674			switch got.Entries[i].ItemID {
675			case idA:
676				ea = &got.Entries[i]
677			case idB:
678				eb = &got.Entries[i]
679			}
680		}
681		if ea.Status != EntryPending {
682			t.Fatalf("重新提交后该项应恢复待处理，got %s", ea.Status)
683		}
684		if eb.Status != EntryConfirmed {
685			t.Fatalf("既有接收结果不应改变，got %s", eb.Status)
686		}
687		if got.Completed() {
688			t.Fatalf("恢复待处理后交接应再次未完成")
689		}
690		r := ea.Rounds[len(ea.Rounds)-1]
691		if r.Reason != "信息不全，需补充图纸" || r.Supplement != "图纸编号已补到资料柜B层" {
692			t.Fatalf("原文退回原因与补充说明都应保留：%+v", r)
693		}
694		if r.SupplementOperator != "张三" || r.ResubmittedAt == nil {
695			t.Fatalf("应记录补充操作人与重新提交时间：%+v", r)
696		}
697	
698		// 重新提交后再次退回，产生第 2 轮历史；再确认接收。
699		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "仍缺签字", "", ""); err != nil {
700			t.Fatalf("second return: %v", err)
701		}
702		got, _ = f.svc.GetHandover(h.ID)
703		for i := range got.Entries {
704			if got.Entries[i].ItemID == idA {
705				ea = &got.Entries[i]
706			}
707		}
708		if len(ea.Rounds) != 2 {
709			t.Fatalf("应保留历次退回记录，期望2轮，got %d", len(ea.Rounds))
710		}
711		if ea.Rounds[0].Reason != "信息不全，需补充图纸" {
712			t.Fatalf("第一轮退回原因不得覆盖：%+v", ea.Rounds[0])
713		}
714		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "签字已补齐"); err != nil {
715			t.Fatalf("resubmit2: %v", err)
716		}
717		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
718			t.Fatalf("final confirm: %v", err)
719		}
720		got, _ = f.svc.GetHandover(h.ID)
721		if !got.Completed() {
722			t.Fatalf("最终应完成")
723		}
724	}
